import java.io.*;
import java.util.*;

public class Main {
    static class OrderStatisticTree {
        long[] key;
        int[] left, right, cnt, size, prio;
        int root, nodes, seed;

        OrderStatisticTree(int maxNodes) {
            key = new long[maxNodes + 1];
            left = new int[maxNodes + 1];
            right = new int[maxNodes + 1];
            cnt = new int[maxNodes + 1];
            size = new int[maxNodes + 1];
            prio = new int[maxNodes + 1];
            root = 0;
            nodes = 0;
            seed = 123456789;
        }

        private int nextRand() {
            seed ^= seed << 13;
            seed ^= seed >>> 17;
            seed ^= seed << 5;
            return seed & 0x7fffffff;
        }

        void add(long k) {
            root = insert(root, k);
        }

        private int insert(int t, long k) {
            if (t == 0) {
                ++nodes;
                key[nodes] = k;
                cnt[nodes] = 1;
                size[nodes] = 1;
                left[nodes] = right[nodes] = 0;
                prio[nodes] = nextRand();
                return nodes;
            }

            if (k == key[t]) {
                cnt[t]++;
                update(t);
                return t;
            } else if (k < key[t]) {
                left[t] = insert(left[t], k);
                if (prio[left[t]] < prio[t]) {
                    t = rotateRight(t);
                }
            } else {
                right[t] = insert(right[t], k);
                if (prio[right[t]] < prio[t]) {
                    t = rotateLeft(t);
                }
            }

            update(t);
            return t;
        }

        int queryLeq(long k) {
            int t = root;
            int res = 0;

            while (t != 0) {
                if (k < key[t]) {
                    t = left[t];
                } else if (k > key[t]) {
                    res += size[left[t]] + cnt[t];
                    t = right[t];
                } else {
                    res += size[left[t]] + cnt[t];
                    break;
                }
            }

            return res;
        }

        private void update(int t) {
            size[t] = size[left[t]] + size[right[t]] + cnt[t];
        }

        private int rotateRight(int t) {
            int l = left[t];
            left[t] = right[l];
            right[l] = t;
            update(t);
            update(l);
            return l;
        }

        private int rotateLeft(int t) {
            int r = right[t];
            right[t] = left[r];
            left[r] = t;
            update(t);
            update(r);
            return r;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null) return;

        int N = Integer.parseInt(first.trim());
        OrderStatisticTree tree = new OrderStatisticTree(N + 5);

        StringBuilder sb = new StringBuilder();
        long prevPenalty = 0;

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());

            long xr = x + prevPenalty;
            long yr = y + prevPenalty;
            long dist = xr * xr + yr * yr;

            int p = tree.queryLeq(dist);
            sb.append(p).append('\n');

            tree.add(dist);
            prevPenalty = p;
        }

        System.out.print(sb.toString());
    }
}
```

